--
-- Table structure for table `wdh_variants`
--

DROP TABLE IF EXISTS `wdh_variants`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wdh_variants` (
  `id` int NOT NULL AUTO_INCREMENT,
  `product_id` int NOT NULL,
  `sku` varchar(100) COLLATE utf8mb4_general_ci DEFAULT '',
  `type` varchar(100) COLLATE utf8mb4_general_ci DEFAULT '',
  `condition_type` varchar(50) COLLATE utf8mb4_general_ci DEFAULT '',
  `cut_type` varchar(100) COLLATE utf8mb4_general_ci DEFAULT '',
  `cut_value` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `skin_type` varchar(100) COLLATE utf8mb4_general_ci DEFAULT '',
  `bone_type` varchar(100) COLLATE utf8mb4_general_ci DEFAULT '',
  `region` varchar(255) COLLATE utf8mb4_general_ci DEFAULT '',
  `short_title` varchar(255) COLLATE utf8mb4_general_ci DEFAULT '',
  `long_title` varchar(255) COLLATE utf8mb4_general_ci DEFAULT '',
  `base_price` decimal(10,4) DEFAULT NULL,
  `discount_price` decimal(10,4) DEFAULT NULL,
  `stock_status` varchar(20) COLLATE utf8mb4_general_ci DEFAULT 'instock',
  `stock_count` int DEFAULT '0',
  `is_featured` varchar(10) COLLATE utf8mb4_general_ci DEFAULT '',
  `per` varchar(100) COLLATE utf8mb4_general_ci DEFAULT '',
  `popularity` int DEFAULT '0',
  `thumbnail` text COLLATE utf8mb4_general_ci,
  `thumbnail_alt` text COLLATE utf8mb4_general_ci,
  `image1` text COLLATE utf8mb4_general_ci,
  `image1_alt` text COLLATE utf8mb4_general_ci,
  `image2` text COLLATE utf8mb4_general_ci,
  `image2_alt` text COLLATE utf8mb4_general_ci,
  `image3` text COLLATE utf8mb4_general_ci,
  `image3_alt` text COLLATE utf8mb4_general_ci,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `fat_level` varchar(50) COLLATE utf8mb4_general_ci DEFAULT '',
  PRIMARY KEY (`id`),
  KEY `fk_wdh_variants_product` (`product_id`),
  CONSTRAINT `fk_wdh_variants_product` FOREIGN KEY (`product_id`) REFERENCES `wdh_products` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=594 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

