DROP TABLE IF EXISTS `wdh_variant_pricing`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wdh_variant_pricing` (
  `id` int NOT NULL AUTO_INCREMENT,
  `variant_id` int NOT NULL,
  `supplier_id` int DEFAULT NULL,
  `label` varchar(50) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `dealer_price` decimal(10,4) DEFAULT NULL,
  `increment` decimal(10,4) DEFAULT NULL,
  `retail_price` decimal(10,4) DEFAULT NULL,
  `sort_order` int DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `fk_wvp_variant` (`variant_id`),
  KEY `fk_wvp_supplier` (`supplier_id`),
  CONSTRAINT `fk_wvp_supplier` FOREIGN KEY (`supplier_id`) REFERENCES `wdh_suppliers` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_wvp_variant` FOREIGN KEY (`variant_id`) REFERENCES `wdh_variants` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=981 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

